package analyzer

import "strings"

// Explicit assertion APIs from testify v1.11.1 generated forwarding methods.
// Constructors and object-comparison utilities are intentionally absent.
func builtinAssertions() map[Symbol]ruleID {
	result := map[Symbol]ruleID{}
	for _, name := range strings.Fields(`Condition Conditionf Contains Containsf DirExists DirExistsf ElementsMatch ElementsMatchf Empty Emptyf Equal EqualError EqualErrorf EqualExportedValues EqualExportedValuesf EqualValues EqualValuesf Equalf Error ErrorAs ErrorAsf ErrorContains ErrorContainsf ErrorIs ErrorIsf Errorf Eventually EventuallyWithT EventuallyWithTf Eventuallyf Exactly Exactlyf Fail FailNow FailNowf Failf False Falsef FileExists FileExistsf Greater GreaterOrEqual GreaterOrEqualf Greaterf HTTPBodyContains HTTPBodyContainsf HTTPBodyNotContains HTTPBodyNotContainsf HTTPError HTTPErrorf HTTPRedirect HTTPRedirectf HTTPStatusCode HTTPStatusCodef HTTPSuccess HTTPSuccessf Implements Implementsf InDelta InDeltaMapValues InDeltaMapValuesf InDeltaSlice InDeltaSlicef InDeltaf InEpsilon InEpsilonSlice InEpsilonSlicef InEpsilonf IsDecreasing IsDecreasingf IsIncreasing IsIncreasingf IsNonDecreasing IsNonDecreasingf IsNonIncreasing IsNonIncreasingf IsNotType IsNotTypef IsType IsTypef JSONEq JSONEqf Len Lenf Less LessOrEqual LessOrEqualf Lessf Negative Negativef Never Neverf Nil Nilf NoDirExists NoDirExistsf NoError NoErrorf NoFileExists NoFileExistsf NotContains NotContainsf NotElementsMatch NotElementsMatchf NotEmpty NotEmptyf NotEqual NotEqualValues NotEqualValuesf NotEqualf NotErrorAs NotErrorAsf NotErrorIs NotErrorIsf NotImplements NotImplementsf NotNil NotNilf NotPanics NotPanicsf NotRegexp NotRegexpf NotSame NotSamef NotSubset NotSubsetf NotZero NotZerof Panics PanicsWithError PanicsWithErrorf PanicsWithValue PanicsWithValuef Panicsf Positive Positivef Regexp Regexpf Same Samef Subset Subsetf True Truef WithinDuration WithinDurationf WithinRange WithinRangef YAMLEq YAMLEqf Zero Zerof`) {
		result[Symbol{Package: "github.com/stretchr/testify/assert", Function: name}] = "TESTO031"
		result[Symbol{Package: "github.com/stretchr/testify/assert", Receiver: "Assertions", Method: name}] = "TESTO031"
	}
	for _, name := range strings.Fields(`Condition Conditionf Contains Containsf DirExists DirExistsf ElementsMatch ElementsMatchf Empty Emptyf Equal EqualError EqualErrorf EqualExportedValues EqualExportedValuesf EqualValues EqualValuesf Equalf Error ErrorAs ErrorAsf ErrorContains ErrorContainsf ErrorIs ErrorIsf Errorf Eventually EventuallyWithT EventuallyWithTf Eventuallyf Exactly Exactlyf Fail FailNow FailNowf Failf False Falsef FileExists FileExistsf Greater GreaterOrEqual GreaterOrEqualf Greaterf HTTPBodyContains HTTPBodyContainsf HTTPBodyNotContains HTTPBodyNotContainsf HTTPError HTTPErrorf HTTPRedirect HTTPRedirectf HTTPStatusCode HTTPStatusCodef HTTPSuccess HTTPSuccessf Implements Implementsf InDelta InDeltaMapValues InDeltaMapValuesf InDeltaSlice InDeltaSlicef InDeltaf InEpsilon InEpsilonSlice InEpsilonSlicef InEpsilonf IsDecreasing IsDecreasingf IsIncreasing IsIncreasingf IsNonDecreasing IsNonDecreasingf IsNonIncreasing IsNonIncreasingf IsNotType IsNotTypef IsType IsTypef JSONEq JSONEqf Len Lenf Less LessOrEqual LessOrEqualf Lessf Negative Negativef Never Neverf Nil Nilf NoDirExists NoDirExistsf NoError NoErrorf NoFileExists NoFileExistsf NotContains NotContainsf NotElementsMatch NotElementsMatchf NotEmpty NotEmptyf NotEqual NotEqualValues NotEqualValuesf NotEqualf NotErrorAs NotErrorAsf NotErrorIs NotErrorIsf NotImplements NotImplementsf NotNil NotNilf NotPanics NotPanicsf NotRegexp NotRegexpf NotSame NotSamef NotSubset NotSubsetf NotZero NotZerof Panics PanicsWithError PanicsWithErrorf PanicsWithValue PanicsWithValuef Panicsf Positive Positivef Regexp Regexpf Same Samef Subset Subsetf True Truef WithinDuration WithinDurationf WithinRange WithinRangef YAMLEq YAMLEqf Zero Zerof`) {
		result[Symbol{Package: "github.com/stretchr/testify/require", Function: name}] = "TESTO031"
		result[Symbol{Package: "github.com/stretchr/testify/require", Receiver: "Assertions", Method: name}] = "TESTO031"
	}
	return result
}
